      border-radius: clamp(14px, 1.8vw, 20px);
      padding: clamp(0.7rem, 1.8vw, 1.35rem);
      display: grid;
      gap: clamp(0.35rem, 0.9vw, 0.75rem);
    }

    .node .title {
      font-family: var(--mono);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      font-size: clamp(0.62rem, 1.0vw, 0.86rem);
      color: rgba(234,240,255,0.65);
    }

    .node .desc {
      font-size: var(--body-size);
      color: rgba(234,240,255,0.82);
      line-height: 1.35;
      font-family: var(--sans);
    }

    .row3 {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr;
      gap: clamp(0.6rem, 1.6vw, 1.1rem);
      align-items: stretch;
    }

    .node.fast { border-color: rgba(110,231,255,0.22); }
    .node.slow { border-color: rgba(215,255,110,0.20); }
    .node.know { border-color: rgba(255,77,125,0.22); }

    .arrow {
      display: flex;
      align-items: center;
      gap: clamp(0.4rem, 1.2vw, 0.8rem);
      font-family: var(--mono);
      font-size: clamp(0.62rem, 1.0vw, 0.86rem);
      color: rgba(234,240,255,0.6);
      padding-left: clamp(0.4rem, 1.0vw, 0.8rem);
    }

    .arrow .chev {
      width: clamp(22px, 3vw, 42px);
      height: 2px;
      background: linear-gradient(90deg, rgba(234,240,255,0.12), rgba(110,231,255,0.35), rgba(234,240,255,0.12));
      position: relative;
      border-radius: 999px;
    }

    .arrow .chev:after {
      content: "";
      position: absolute;
      right: 0;
      top: 50%;
      width: 10px;
      height: 10px;
      border-right: 2px solid rgba(110,231,255,0.55);
      border-top: 2px solid rgba(110,231,255,0.55);
      transform: translateY(-50%) rotate(45deg);
      border-radius: 2px;
    }

    /* === Chart styles === */
    .chart {
      max-width: min(1200px, 92vw);
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1.05fr 0.95fr;
      gap: clamp(0.8rem, 2.2vw, 2.0rem);
      align-items: center;
    }

    .bars {
      display: grid;
      gap: clamp(0.5rem, 1.2vw, 0.9rem);
    }

    .bar {
      border: 1px solid rgba(255,255,255,0.12);
      background: rgba(255,255,255,0.03);
      border-radius: 14px;
      padding: clamp(0.45rem, 1.1vw, 0.85rem);
      overflow: hidden;
    }

    .bar-head {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: baseline;
      font-family: var(--mono);
      font-size: clamp(0.6rem, 1.0vw, 0.85rem);
      color: rgba(234,240,255,0.72);
      margin-bottom: clamp(0.3rem, 0.7vw, 0.55rem);
    }

    .tracks {
      display: grid;
      gap: clamp(0.25rem, 0.6vw, 0.45rem);
    }

    .track {
      height: clamp(8px, 1.1vw, 12px);
      border-radius: 999px;
      background: rgba(255,255,255,0.06);
      overflow: hidden;
      position: relative;
    }

    .fill {
      height: 100%;
      border-radius: 999px;
    }

    .fill.acc {
      background: linear-gradient(90deg, rgba(110,231,255,0.35), rgba(110,231,255,0.85));
      box-shadow: 0 0 18px rgba(110,231,255,0.18);
    }

    .fill.know {
      background: linear-gradient(90deg, rgba(215,255,110,0.35), rgba(215,255,110,0.85));
      box-shadow: 0 0 18px rgba(215,255,110,0.16);
    }

    .legend {
      display: flex;
      gap: clamp(0.6rem, 1.2vw, 1rem);
      flex-wrap: wrap;
      font-family: var(--mono);
      font-size: clamp(0.58rem, 0.95vw, 0.82rem);
      color: rgba(234,240,255,0.62);
      margin-top: clamp(0.35rem, 0.9vw, 0.75rem);
    }

    .key {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
    }

    .swatch {
      width: clamp(10px, 1.1vw, 14px);
      height: clamp(10px, 1.1vw, 14px);
      border-radius: 4px;
      background: rgba(255,255,255,0.2);
    }

    .swatch.a { background: rgba(110,231,255,0.8); }
    .swatch.k { background: rgba(215,255,110,0.8); }

    /* === Small footer note === */
    .foot {
      font-family: var(--mono);
      font-size: clamp(0.55rem, 0.95vw, 0.82rem);
      color: rgba(234,240,255,0.55);
      margin-top: clamp(0.4rem, 0.9vw, 0.8rem);
      max-width: min(110ch, 92vw);
    }

    /* === Responsive tweaks for dense slides === */
    @media (max-width: 980px) {
      .two-col { grid-template-columns: 1fr; }
      .chart { grid-template-columns: 1fr; }
      .row3 { grid-template-columns: 1fr; }
    }
  </style>
</head>

<body>

  <!-- =====================================================
       Slide 1: Title
       ===================================================== -->
  <section class="slide" id="slide-1">
    <div class="corner decorative"></div>
    <div class="orb a decorative"></div>
    <div class="orb b decorative"></div>
    <div class="slide-number">01 / 08</div>

    <div class="slide-content">
      <div class="two-col">
        <div>
          <div class="kicker reveal">LLM agents · planning systems · self-awareness</div>
          <h1 class="reveal d2 glow">KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge</h1>
          <div class="lede reveal d3">Agentic knowledgeable self-awareness: learn situational tokens that regulate direct actions, self-reflection, and external knowledge retrieval during interactive planning.</div>
          <div class="meta reveal d4">
            <div class="pill">Source: arXiv:2504.03553</div>
            <div class="pill">Focus: selective knowledge usage</div>
            <div class="pill">ALFWorld benchmark</div>
          </div>
        </div>

        <div class="frame reveal d3">
          <div class="kicker">One-liner</div>
          <div style="font-size: var(--body-size); color: rgba(234,240,255,0.86); line-height: 1.38; margin-top: var(--element-gap);">
            KnowSelf enables agents to autonomously decide when to act directly, when to reflect, and when to consult external knowledge—avoiding indiscriminate “flood irrigation.”
          </div>
          <div class="foot" style="margin-top: var(--content-gap);">
            Audience: ML researchers & graduate students interested in LLM-based agents and planning systems.
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- =====================================================
       Slide 2: Problem framing
       ===================================================== -->
  <section class="slide" id="slide-2">
    <div class="corner decorative"></div>
    <div class="orb a decorative" style="opacity:0.35"></div>
    <div class="slide-number">02 / 08</div>

    <div class="slide-content">
      <div class="kicker reveal">Problem</div>
      <h2 class="reveal d2">Current agent training uses <span class="accent">“flood irrigation”</span> — indiscriminate knowledge injection hurts efficiency</h2>

      <div class="three-col" style="margin-top: var(--content-gap);">
        <div class="node reveal d3">
          <div class="title">Trajectory imitation</div>
          <div class="desc"><span class="method">ReAct</span>-style learning: fit gold trajectories even when the agent could have acted directly—risking fragile pattern fitting.</div>
        </div>
        <div class="node reveal d4">
          <div class="title">Trial-and-error refinement</div>
          <div class="desc"><span class="method">Reflexion</span>-style loops: external feedback is injected regardless of whether reflection is actually needed at a step.</div>
        </div>
        <div class="node reveal d5">
          <div class="title">Knowledge-augmented planning</div>
          <div class="desc"><span class="method">KnowAgent / WKM</span>: consult knowledge on <span class="hi">100%</span> of steps—unnecessarily increasing inference cost and sometimes hurting performance.</div>
        </div>
      </div>

      <ul class="bullets" style="margin-top: var(--content-gap);">
        <li class="reveal d3"><span class="dot"></span><span>Key mismatch: injection is <span class="hi">situationally blind</span>—it ignores whether the agent can already solve the step.</span></li>
        <li class="reveal d4"><span class="dot"></span><span>Observed consequences: fragile planning, pattern collapse on unexpected inputs, and high inference costs.</span></li>
        <li class="reveal d5"><span class="dot"></span><span>Human contrast: metacognitive self-awareness—“can I act now, should I reflect, or do I need outside help?”</span></li>
      </ul>
    </div>
  </section>

  <!-- =====================================================
       Slide 3: Three thinking modes (decision tree)
       ===================================================== -->
  <section class="slide" id="slide-3">
    <div class="corner decorative"></div>
    <div class="orb b decorative" style="opacity:0.35"></div>
    <div class="slide-number">03 / 08</div>

    <div class="slide-content">
      <div class="kicker reveal">KnowSelf taxonomy</div>
      <h2 class="reveal d2">Three situational modes: <span class="accent">fast</span>, <span class="accent2">slow</span>, and <span class="danger">knowledgeable</span> thinking</h2>

      <div class="diagram" style="margin-top: var(--content-gap);">
        <div class="node reveal d3" style="max-width: min(1040px, 92vw); margin: 0 auto;">
          <div class="title">Decision criterion (per step)</div>
          <div class="desc">Compare predicted action to the gold action; if wrong, test whether <span class="hi">reflection</span> can self-correct; otherwise, require <span class="hi">external knowledge</span>.</div>
        </div>

        <div class="arrow reveal d3" style="max-width: min(1040px, 92vw); margin: 0.3rem auto 0 auto;">
          <div class="chev"></div>
          <div>Route to one of three modes</div>
        </div>

        <div class="row3" style="max-width: min(1220px, 92vw); margin: 0 auto;">
          <div class="node fast reveal d4">
            <div class="title">Fast thinking</div>
            <div class="desc"><span class="badge"><span class="accent">FAST</span> · direct</span><br/>
              Agent can directly produce the correct action with minimal deliberation.</div>
          </div>
          <div class="node slow reveal d4">
            <div class="title">Slow thinking</div>
            <div class="desc"><span class="badge"><span class="accent2">SLOW</span> · reflect</span><br/>
              Agent initially produces an incorrect action but self-corrects through reflection.</div>
          </div>
          <div class="node know reveal d4">
            <div class="title">Knowledgeable thinking</div>
            <div class="desc"><span class="badge"><span class="danger">KNOW</span> · retrieve</span><br/>
              Agent cannot produce the correct action even after reflection and must consult external knowledge.</div>
          </div>
        </div>

        <div class="foot reveal d5">KnowSelf learns to generate special situation tokens at inference time that trigger <span class="hi">direct action</span>, <span class="hi">reflection</span>, or <span class="hi">knowledge retrieval</span>.</div>
      </div>
    </div>
  </section>

  <!-- =====================================================
       Slide 4: Pipeline
       ===================================================== -->
  <section class="slide" id="slide-4">
    <div class="corner decorative"></div>
    <div class="slide-number">04 / 08</div>

    <div class="slide-content">
      <div class="kicker reveal">Method</div>
      <h2 class="reveal d2">KnowSelf framework: <span class="accent">data construction</span> → <span class="accent2">two-stage training</span> → <span class="danger">self-aware inference</span></h2>

      <div class="two-col" style="margin-top: var(--content-gap); align-items: start;">
        <div class="frame reveal d3">
          <div class="kicker">End-to-end pipeline (Figure 3)</div>
          <img alt="KnowSelf framework figure" src="../benchmark/assets/figure_3.jpg" style="width: 100%; border-radius: 14px; border: 1px solid rgba(255,255,255,0.10);"/>
          <div class="foot">Figure: data construction, learning, and inference pipeline.</div>
        </div>

        <div>
          <div class="node reveal d3" style="margin-bottom: var(--element-gap);">
            <div class="title">Step 1 — Self-awareness data construction</div>
            <div class="desc">Self-explore trajectories; heuristically label each step: match gold → <span class="accent">fast</span>; reflection fixes → <span class="accent2">slow</span>; else → <span class="danger">knowledgeable</span>. Insert special tokens.</div>
          </div>
          <div class="node reveal d4" style="margin-bottom: var(--element-gap);">
            <div class="title">Step 2 — Two-stage training</div>
            <div class="desc">Train with <span class="hi">SFT</span> to learn initial token patterns, then refine with <span class="hi">RPO</span> to improve token generation quality.</div>
          </div>
          <div class="node reveal d5">
            <div class="title">Step 3 — Self-aware inference</div>
            <div class="desc">At deployment, the agent generates tokens that selectively trigger <span class="hi">reflection</span> or <span class="hi">knowledge retrieval</span>—reducing unnecessary calls.</div>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- =====================================================
       Slide 5: Qualitative examples
       ===================================================== -->
  <section class="slide" id="slide-5">
    <div class="corner decorative"></div>
    <div class="orb a decorative" style="opacity:0.25"></div>
    <div class="slide-number">05 / 08</div>

    <div class="slide-content">
      <div class="kicker reveal">Qualitative</div>
      <h2 class="reveal d2">KnowSelf correctly heats a mug and places a saltshaker where baselines fail</h2>

      <div class="two-col" style="margin-top: var(--content-gap);">
        <div class="frame reveal d3">
          <div class="kicker">Figure 1</div>
          <img alt="Qualitative comparison figure" src="../benchmark/assets/figure_1.jpg" style="width: 100%; border-radius: 14px; border: 1px solid rgba(255,255,255,0.10);"/>
          <div class="foot">Figure: KnowSelf vs. OpenAI-O1 and DeepSeek-R1 on ALFWorld tasks.</div>
        </div>

        <div>
          <div class="node reveal d3" style="margin-bottom: var(--element-gap);">
            <div class="title">Task A — “put a hot mug in cabinet”</div>
            <div class="desc"><span class="method">OpenAI-O1</span> opens microwave then incorrectly tries to take an egg; <span class="method">KnowSelf (Llama-8B)</span> emits a <span class="accent2">Reflection</span> token and realizes it should heat the mug using the open microwave.</div>
          </div>
          <div class="node reveal d4">
            <div class="title">Task B — “put a saltshaker in drawer”</div>
            <div class="desc"><span class="method">DeepSeek-R1</span> reflects and attempts to close the drawer first (fails); <span class="method">KnowSelf</span> applies a <span class="danger">Knowledge</span> token noting it should place the object without removing unrelated items.</div>
          </div>
          <div class="foot reveal d5">Interpretation: situational tokens gate *which* cognitive resource to spend—reflection vs retrieval—rather than always invoking both.</div>
        </div>
      </div>
    </div>
  </section>

